 * What may be asked for, out of the snapshot the table last wrote.
 *
 * Whether a move is on offer depends on the pack's conditions and on what
 * the run has already spent, so the device holding both is the only thing
 * that can say. The server carries the answer rather than works it out. A
 * snapshot written before this was published names nothing, which reads as
 * a run with nothing to ask for rather than an error.
 */
function askMenuOf(snapshot: unknown): AskMenu {
  const asks = isRecord(snapshot) && isRecord(snapshot["asks"]) ? snapshot["asks"] : null;
  const listed = asks && Array.isArray(asks["moves"]) ? asks["moves"] : [];
  return {
    roll: asks?.["roll"] === true,
    moves: listed.flatMap((m) => (isRecord(m) && str(m["id"]) && str(m["label"]) ? [{ id: m["id"], label: m["label"] }] : [])),
  };
}

/** The menu as a chat line, in the pack's own words. */
function sayMenu(menu: AskMenu): string {
  const named = menu.moves.map((m) => m.label).join(", ");
  if (menu.roll && menu.moves.length > 0) return `Ask for a roll, or a move: ${named}.`;
  if (menu.roll) return "A table is waiting. Ask for a roll.";
  if (menu.moves.length > 0) return `Moves to ask for: ${named}.`;
  return "Nothing can be asked for right now.";
}
/** How many of an account's runs a watch key will list: a chooser, not a library. */
const STREAM_RUNS_LISTED = 10;
const ASK_KINDS = new Set(["move", "roll"]);
const ASK_ID = /^[a-z][a-zA-Z0-9_-]{0,63}$/;
const isPolicy = (v: unknown): v is AskPolicy => v === "ask" || v === "auto";

/** What a watcher may send back: a few emoji, nothing typed. */
const REACTIONS = new Set(["👏", "🔥", "😮", "😂", "💀", "❤️"]);

/**
 * The metrics document a stream plugin reads: the owner's snapshot with
 * its log left out and its clocks stamped, so a plugin can tick them
 * from `at` without knowing the pack. The shape is the snapshot's own
 * (`v: 1`), which the app's widgets draw, so a plugin draws what a
 * widget would. Nothing here is the pack's text; a snapshot never
 * carries it.
 */
export function metricsOf(
  run: { id: string; packId: string; packTitle: string | null; name: string | null; endedAt: string | null },
  snap: { at: string; snapshot: unknown } | null,
  serverAt: string,
): Record<string, unknown> {
  const s = isRecord(snap?.snapshot) ? snap.snapshot : null;
  if (!s) return { ready: false, run, serverAt };
  const { log: _log, ...rest } = s;
  return { ready: true, run, serverAt, at: snap!.at, ...rest };
}

/**
 * What a release-scoped key may reach: who it is, its claims (signing
 * refuses an unclaimed key), its own library's packs, and the publisher's
 * packs and listings. Nothing that reads play, moves money, or changes who
 * is at the table.
 *
 * Taking a listing down is on the list because the seeder does it: a pack
 * that stops shipping has to stop being offered, and the only party that
 * knows which those are is the deploy that no longer names them. Deleting
 * the product itself is not, since that discards the master.
 */
function releaseMayReach(method: string, path: string): boolean {
  if (
    method === "GET" &&
    (path === "/api/me" || path === "/api/claims" || path === "/api/publishers/me" || path === "/api/publishers/packs")
  )
    return true;
  if (method === "POST" && path === "/api/claims/nonce") return true;
  if (path.startsWith("/api/packs/")) return method === "PUT" || method === "GET";
  if (/^\/api\/publishers\/packs\/[^/]+$/.test(path)) return method === "PUT" || method === "GET";
  if (/^\/api\/publishers\/packs\/[^/]+\/listing$/.test(path)) return method === "POST" || method === "DELETE";
  return false;
}
const MAX_KEYS = 20;
const hashKey = (value: string) => createHash("sha256").update(value).digest("hex");

/** Invitations one person may send in an hour. Generous for a table, mean for a spammer. */

