  await call(request("GET", "/api/public/runs/01RUN/asks?k=askkey&kind=roll&name=viewer_42", { token: null }), d);
  const again = await call(request("GET", "/api/public/runs/01RUN/asks?k=askkey&kind=roll&name=viewer_42", { token: null }), d);
  expect(again.status).toBe(200);
  expect(again.body["ok"]).toBe(false);
  expect(again.body["say"]).toMatch(/second/);
});

it("says what may be asked for when no kind is given, from what the table last published", async () => {
  const d = deps(memoryStore(), { token: () => "askkey" });
  await call(request("POST", "/api/sessions", { body: sessionBody }), d);
  await call(request("POST", "/api/sessions/01RUN/ask-key"), d);
  await call(
    request("PUT", "/api/sessions/01RUN/snapshot", {
      body: {
        snapshot: { v: 1, packTitle: "Any Given Day", asks: { roll: true, moves: [{ id: "salvage", label: "Salvage a Piece" }] } },
      },
    }),
    d,
  );
  const menu = await call(request("GET", "/api/public/runs/01RUN/asks?k=askkey", { token: null }), d);
  expect(menu.status).toBe(200);
  expect(menu.body["ok"]).toBe(true);
  expect(menu.body["roll"]).toBe(true);
  expect(menu.body["moves"]).toEqual([{ id: "salvage", label: "Salvage a Piece" }]);
  // The sentence is what a !moves command would put in chat, in the pack's own words.
  expect(menu.body["say"]).toContain("Salvage a Piece");
  // Reading the menu is not a press: nothing is queued by it.
  expect((await call(request("GET", "/api/sessions/01RUN/asks"), d)).body["asks"]).toHaveLength(0);
});

it("mints an account's two stream keys, shows each once, and kills the one it replaces", async () => {
  let minted = 0;
  const d = deps(memoryStore(), { token: () => `key${(minted += 1)}` });
  // Nothing until asked for, and the server never hands a key back twice.
  expect((await call(request("GET", "/api/me/stream-keys"), d)).body).toEqual({ keys: {} });
  const watch = await call(request("POST", "/api/me/stream-keys", { body: { kind: "watch" } }), d);
  expect(watch.body["key"]).toBe("key1");
  const press = await call(request("POST", "/api/me/stream-keys", { body: { kind: "press" } }), d);
  expect(press.body["key"]).toBe("key2");
  const listed = await call(request("GET", "/api/me/stream-keys"), d);
  expect(listed.body["keys"]).toMatchObject({
    watch: { madeAt: expect.any(String) as unknown as string },
    press: { madeAt: expect.any(String) as unknown as string },
  });
  expect(JSON.stringify(listed.body)).not.toContain("key1");
  // Minting again replaces: the old one opens nothing from that moment.
  await call(request("POST", "/api/me/stream-keys", { body: { kind: "watch" } }), d);
  expect((await call(request("GET", "/api/public/stream/runs?k=key1", { token: null }), d)).body["ok"]).toBe(false);
  expect((await call(request("GET", "/api/public/stream/runs?k=key3", { token: null }), d)).body["ok"]).toBe(true);
  // A kind that is not one of the two is refused, and either can be killed on its own.
  expect((await call(request("POST", "/api/me/stream-keys", { body: { kind: "both" } }), d)).status).toBe(422);
  expect((await call(request("DELETE", "/api/me/stream-keys?kind=press"), d)).body).toEqual({
    keys: { watch: { madeAt: expect.any(String) as unknown as string } },
  });
});

it("reads the numbers of the run in play by a watch key, so no one picks a link apart for a token", async () => {
  let minted = 0;
  const d = deps(memoryStore(), { token: () => `key${(minted += 1)}` });
  const watch = await call(request("POST", "/api/me/stream-keys", { body: { kind: "watch" } }), d);
  const k = String(watch.body["key"]);
  expect((await call(request("GET", `/api/public/stream/metrics?k=${k}`, { token: null }), d)).body["ok"]).toBe(false);
  await call(request("POST", "/api/sessions", { body: sessionBody }), d);
  await call(request("POST", "/api/sessions/01RUN/public"), d);
  const numbers = await call(request("GET", `/api/public/stream/metrics?k=${k}`, { token: null }), d);
  expect(numbers.status).toBe(200);
  expect(numbers.body["ok"]).toBe(true);
  expect(numbers.body["runId"]).toBe("01RUN");
  // The same document the per-run address answers with: what it says about
  // the run sits under `run`, and `ready` is false until the table has
  // written a snapshot.
  expect(numbers.body["ready"]).toBe(false);
  expect(numbers.body["run"]).toMatchObject({ id: "01RUN", packTitle: "The Pack" });
  // A press key presses; it does not read.
  const press = await call(request("POST", "/api/me/stream-keys", { body: { kind: "press" } }), d);
  expect((await call(request("GET", `/api/public/stream/metrics?k=${String(press.body["key"])}`, { token: null }), d)).body["ok"]).toBe(
    false,
  );
});

