  expect((await call(request("DELETE", "/api/sessions/01RUN/public"), d)).body).toEqual({ shared: false });
  expect((await call(request("GET", "/api/public/runs/01RUN?t=livetok", { token: null }), d)).body).toEqual({ found: false });
